import sys
from itertools import product

n = int(sys.stdin.read().split()[0])
MOD = 10**9 + 7
if n <= 18:
    count = 0
    for bits in product('01', repeat=n):
        s = ''.join(bits)
        if '11' not in s:
            count += 1
    print(count % MOD)
else:
    a, b = 1, 2
    for _ in range(n):
        a, b = b, a + b
    print(a % MOD)

